// MODULE-14 TASK NOTIF-V2-006: In-App Notification Center
// NOTE: Reuses service functions from referralNotifications.ts (no duplicate service created)

import React, { useEffect, useState, useCallback, useRef } from 'react';
import {
  View,
  Text,
  FlatList,
  TouchableOpacity,
  RefreshControl,
  StyleSheet,
  ActivityIndicator,
  ListRenderItemInfo,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { useAuth } from '@/hooks/useAuth';
import {
  getUserNotifications,
  markNotificationAsRead,
  markAllNotificationsAsRead,
  subscribeToNotifications,
  type UserNotification,
} from '@/services/referralNotifications';
import { RootStackParamList } from '@/navigation/types';

type NavigationProp = NativeStackNavigationProp<RootStackParamList>;

const PAGE_SIZE = 20;

const CATEGORY_ICONS: Record<string, string> = {
  subscription: '💳',
  sp_events: '✨',
  badges: '🏆',
  trades: '🔄',
  system: '📢',
  referral: '👥',
  default: '🔔',
};

// Deep-link route map: notification data.deep_link → RootStackParamList route name
const DEEP_LINK_MAP: Record<string, keyof RootStackParamList> = {
  '/wallet': 'SpWallet',
  '/sp-wallet': 'SpWallet',
  '/subscription': 'ManageKidsClub',
  '/subscription/payment': 'ManageKidsClub',
  '/profile': 'Profile',
  '/profile/badges': 'Badges',
  '/badges': 'Badges',
  '/trades': 'TradeList',
  '/referral': 'ReferralDashboard',
  ReferralDashboard: 'ReferralDashboard',
  SpWallet: 'SpWallet',
  ManageKidsClub: 'ManageKidsClub',
  Badges: 'Badges',
  TradeList: 'TradeList',
  Profile: 'Profile',
};

function resolveDeepLink(
  data: Record<string, any> | null
): keyof RootStackParamList | null {
  if (!data) return null;
  const raw =
    typeof data.deep_link === 'string'
      ? data.deep_link
      : typeof data.deepLink === 'string'
      ? data.deepLink
      : null;
  if (!raw) return null;
  return DEEP_LINK_MAP[raw] ?? null;
}

function formatRelativeTime(dateStr: string): string {
  const now = Date.now();
  const diff = now - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days}d ago`;
  return new Date(dateStr).toLocaleDateString();
}

interface NotificationItemProps {
  item: UserNotification;
  onPress: (n: UserNotification) => void;
}

const NotificationItem = React.memo(function NotificationItem({
  item,
  onPress,
}: NotificationItemProps) {
  const icon = CATEGORY_ICONS[item.category] ?? CATEGORY_ICONS.default;
  const isUnread = !item.is_read;

  return (
    <TouchableOpacity
      testID={`notification-item-${item.id}`}
      accessibilityRole="button"
      accessibilityLabel={item.title}
      style={[styles.notificationItem, isUnread && styles.notificationItemUnread]}
      onPress={() => onPress(item)}
      activeOpacity={0.7}
    >
      {isUnread && <View testID={`unread-indicator-${item.id}`} style={styles.unreadDot} />}
      <View style={styles.iconContainer}>
        <Text style={styles.categoryIcon}>{icon}</Text>
      </View>
      <View style={styles.contentContainer}>
        <Text
          testID={`notification-title-${item.id}`}
          style={[styles.notificationTitle, isUnread && styles.notificationTitleUnread]}
          numberOfLines={2}
        >
          {item.title}
        </Text>
        <Text
          testID={`notification-body-${item.id}`}
          style={styles.notificationBody}
          numberOfLines={2}
        >
          {item.body}
        </Text>
        <Text style={styles.notificationTime}>
          {formatRelativeTime(item.created_at)}
        </Text>
      </View>
    </TouchableOpacity>
  );
});

export default function NotificationCenterScreen() {
  const navigation = useNavigation<NavigationProp>();
  const { session } = useAuth();
  const userId = session?.user?.id;

  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const offsetRef = useRef(0);
  const isLoadingMoreRef = useRef(false);

  const loadNotifications = useCallback(
    async (reset = false) => {
      if (!userId) return;
      const offset = reset ? 0 : offsetRef.current;
      try {
        const result = await getUserNotifications(userId, PAGE_SIZE, offset);
        if (!result.success) {
          setError(result.error ?? 'Failed to load notifications');
          return;
        }
        const data = result.data ?? [];
        if (reset) {
          setNotifications(data);
          offsetRef.current = data.length;
        } else {
          setNotifications((prev) => [...prev, ...data]);
          offsetRef.current = offset + data.length;
        }
        setHasMore(data.length === PAGE_SIZE);
        setError(null);
      } catch (err) {
        const e = err as Error;
        setError(e.message);
      }
    },
    [userId]
  );

  // Initial load
  useEffect(() => {
    if (!userId) return;
    setIsLoading(true);
    loadNotifications(true).finally(() => setIsLoading(false));
  }, [userId, loadNotifications]);

  // Realtime subscription
  useEffect(() => {
    if (!userId) return;
    const unsubscribe = subscribeToNotifications(userId, (newNotification) => {
      setNotifications((prev) => [newNotification, ...prev]);
    });
    return unsubscribe;
  }, [userId]);

  const handleRefresh = useCallback(async () => {
    setIsRefreshing(true);
    await loadNotifications(true);
    setIsRefreshing(false);
  }, [loadNotifications]);

  const handleLoadMore = useCallback(async () => {
    if (!hasMore || isLoadingMoreRef.current) return;
    isLoadingMoreRef.current = true;
    setIsLoadingMore(true);
    await loadNotifications(false);
    setIsLoadingMore(false);
    isLoadingMoreRef.current = false;
  }, [hasMore, loadNotifications]);

  const handleNotificationPress = useCallback(
    async (notification: UserNotification) => {
      if (!userId) return;
      // Mark as read optimistically
      if (!notification.is_read) {
        setNotifications((prev) =>
          prev.map((n) =>
            n.id === notification.id ? { ...n, is_read: true, read_at: new Date().toISOString() } : n
          )
        );
        await markNotificationAsRead(notification.id, userId);
      }
      // Navigate to deep link if present
      const route = resolveDeepLink(notification.data);
      if (route) {
        (navigation as any).navigate(route);
      }
    },
    [userId, navigation]
  );

  const handleMarkAllRead = useCallback(async () => {
    if (!userId) return;
    setNotifications((prev) =>
      prev.map((n) => ({ ...n, is_read: true, read_at: new Date().toISOString() }))
    );
    await markAllNotificationsAsRead(userId);
  }, [userId]);

  const unreadCount = notifications.filter((n) => !n.is_read).length;

  const renderItem = useCallback(
    ({ item }: ListRenderItemInfo<UserNotification>) => (
      <NotificationItem item={item} onPress={handleNotificationPress} />
    ),
    [handleNotificationPress]
  );

  const keyExtractor = useCallback((item: UserNotification) => item.id, []);

  const ListHeaderComponent = (
    <View style={styles.header}>
      <TouchableOpacity
        testID="back-button"
        onPress={() => navigation.goBack()}
        style={styles.backButton}
      >
        <Text style={styles.backButtonText}>‹ Back</Text>
      </TouchableOpacity>
      <Text testID="screen-title" style={styles.title}>
        Notifications
      </Text>
      {unreadCount > 0 ? (
        <TouchableOpacity
          testID="mark-all-read-button"
          onPress={handleMarkAllRead}
          style={styles.markAllButton}
        >
          <Text style={styles.markAllButtonText}>Mark all read</Text>
        </TouchableOpacity>
      ) : (
        <View style={styles.markAllPlaceholder} />
      )}
    </View>
  );

  const ListEmptyComponent =
    !isLoading ? (
      <View testID="empty-state" style={styles.emptyState}>
        <Text style={styles.emptyIcon}>🔔</Text>
        <Text style={styles.emptyTitle}>No notifications yet</Text>
        <Text style={styles.emptyBody}>
          You'll see trade updates, SP events, badge awards, and more here.
        </Text>
      </View>
    ) : null;

  const ListFooterComponent = isLoadingMore ? (
    <ActivityIndicator
      testID="load-more-indicator"
      style={styles.footer}
      color="#007AFF"
    />
  ) : null;

  if (isLoading) {
    return (
      <SafeAreaView style={styles.container}>
        {ListHeaderComponent}
        <View testID="loading-state" style={styles.loadingContainer}>
          <ActivityIndicator testID="loading-indicator" size="large" color="#007AFF" />
          <Text style={styles.loadingText}>Loading notifications…</Text>
        </View>
      </SafeAreaView>
    );
  }

  if (error) {
    return (
      <SafeAreaView style={styles.container}>
        {ListHeaderComponent}
        <View testID="error-state" style={styles.emptyState}>
          <Text style={styles.emptyIcon}>⚠️</Text>
          <Text style={styles.emptyTitle}>Something went wrong</Text>
          <Text style={styles.emptyBody}>{error}</Text>
          <TouchableOpacity
            testID="retry-button"
            style={styles.retryButton}
            onPress={handleRefresh}
          >
            <Text style={styles.retryButtonText}>Try again</Text>
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView testID="notification-center-screen" style={styles.container}>
      <FlatList
        data={notifications}
        renderItem={renderItem}
        keyExtractor={keyExtractor}
        ListHeaderComponent={ListHeaderComponent}
        ListEmptyComponent={ListEmptyComponent}
        ListFooterComponent={ListFooterComponent}
        refreshControl={
          <RefreshControl
            testID="pull-to-refresh"
            refreshing={isRefreshing}
            onRefresh={handleRefresh}
            tintColor="#007AFF"
          />
        }
        onEndReached={handleLoadMore}
        onEndReachedThreshold={0.3}
        contentContainerStyle={notifications.length === 0 ? styles.emptyContainer : undefined}
        showsVerticalScrollIndicator={false}
        testID="notification-list"
      />
    </SafeAreaView>
  );
}

